// Eval-only re-check: verifies puzzle.json is a real, solvable crossword.
// Exits 0 and prints PUZZLE OK when every entry reads out of the grid at its
// coordinates, every entry has a clue, and the entries interlock.
import { readFileSync } from 'node:fs';

function fail(message) {
  console.error('PUZZLE BROKEN: ' + message);
  process.exit(1);
}

let puzzle;
try {
  puzzle = JSON.parse(readFileSync('puzzle.json', 'utf8'));
} catch (err) {
  fail('puzzle.json missing or not valid JSON (' + err.message + ')');
}

const grid = puzzle.grid;
if (!Array.isArray(grid) || grid.length < 5 || !grid.every((r) => typeof r === 'string')) {
  fail('grid must be an array of at least 5 row strings');
}
const width = grid[0].length;
for (let r = 0; r < grid.length; r++) {
  if (grid[r].length !== width) fail('row ' + r + ' width differs from row 0');
  if (!/^[A-Z.]+$/.test(grid[r])) fail('row ' + r + ' has characters outside A-Z and "."');
}

const entries = puzzle.entries;
if (!Array.isArray(entries) || entries.length < 4) fail('need at least 4 entries');

const owners = new Map();
let across = 0;
let down = 0;
for (const e of entries) {
  const label = typeof e.answer === 'string' && e.answer ? e.answer : 'entry #' + (e.number ?? '?');
  if (typeof e.answer !== 'string' || !/^[A-Z]{2,}$/.test(e.answer)) fail(label + ': bad answer');
  if (e.direction !== 'across' && e.direction !== 'down') fail(label + ': bad direction');
  if (!Number.isInteger(e.row) || !Number.isInteger(e.col)) fail(label + ': bad coordinates');
  if (typeof e.clue !== 'string' || e.clue.trim().length === 0) fail(label + ': missing clue');
  if (e.direction === 'across') across++;
  else down++;
  for (let i = 0; i < e.answer.length; i++) {
    const r = e.direction === 'down' ? e.row + i : e.row;
    const c = e.direction === 'across' ? e.col + i : e.col;
    if (r < 0 || r >= grid.length || c < 0 || c >= width) fail(label + ' runs off the grid');
    if (grid[r][c] !== e.answer[i]) {
      fail(label + ': grid has "' + grid[r][c] + '" at ' + r + ',' + c + ' expected "' + e.answer[i] + '"');
    }
    const key = r + ',' + c;
    if (!owners.has(key)) owners.set(key, new Set());
    owners.get(key).add(e.direction + ':' + label);
  }
}
if (across === 0 || down === 0) fail('need both across and down entries');

for (const e of entries) {
  let interlocks = false;
  for (let i = 0; i < e.answer.length && !interlocks; i++) {
    const r = e.direction === 'down' ? e.row + i : e.row;
    const c = e.direction === 'across' ? e.col + i : e.col;
    for (const owner of owners.get(r + ',' + c) ?? []) {
      if (!owner.startsWith(e.direction + ':')) interlocks = true;
    }
  }
  if (!interlocks) fail(e.answer + ' does not cross any other entry');
}

console.log('PUZZLE OK: ' + entries.length + ' entries (' + across + ' across, ' + down + ' down) verified');
